 "content": "def transform(grid):
    """Find every zero-cell occurrence of the shape formed by the 8 clue."""
    h, w = len(grid), len(grid[0])
    clue = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 8]
    if not clue:
        return [row[:] for row in grid]
    min_r = min(r for r, c in clue)
    min_c = min(c for r, c in clue)
    shape = [(r - min_r, c - min_c) for r, c in clue]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if all(r + dr < h and c + dc < w and grid[r + dr][c + dc] == 0
                   for dr, dc in shape):
                for dr, dc in shape:
                    out[r + dr][c + dc] = 8
    return out
